import{_ as a,a as n}from"./chunks/mmad_hf32_950.QOU-hNyO.js";import{_ as p,o as c,a as e,b as l}from"./app.C41L12d5.js";const S=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"Mmad计算关键特性说明","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/mmad_compute_key_features"},{"text":"HF32","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/HF32"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/HF32.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/HF32.md","lastUpdated":1787104771000}'),t={name:"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/HF32.md"};function o(_,s,d,i,m,r){return c(),e("div",null,[...s[0]||(s[0]=[l('<div><article class="markdown-body"><h1>HF32<span id="ZH-CN_TOPIC_0000002538231188"></span></h1><p><strong>特性说明：</strong></p><p>HF32的核心功能体现为：用户在输入矩阵A、B矩阵都为fp32数据类型的场景下，当配置开启HF32开关后，fp32数据在执行矩阵乘法运算前会被转换并舍入为HF32（half-fp32）格式。这种做法可使Mmad（f322f32）接口的计算性能提升至原来的两倍，但会带来一定的精度损失。需要注意的是，尽管中间计算使用HF32格式，最终的运算结果仍以fp32格式输出，以保证后续处理的兼容性。</p><p>舍入模式说明：fp32至HF32转换过程中的舍入模式由SetHF32TransMode接口配置。当HF32模式开启且设置TransMode为NEAREST_AWAY时，FP32将以向最接近的值舍入，平局时远离零的方式舍入为HF32；若设置TransMode为NEAREST_EVEN时，FP32将以向最接近的值舍入，平局时向偶数舍入的方式舍入为HF32。</p><p><strong>图1</strong> HF32数值精度示意图<a id="zh_cn_topic_mmad_keyfunc_section1_figure1"></a></p><p><img src="'+a+'" alt="HF32数值精度示意图" title="HF32数值精度示意图"></p><div data-filter="950"><p>注意，针对Ascend 950PR/Ascend 950DT产品，其HF32格式的尾数位为10位，示意图如图2所示：</p><p><strong>图2</strong> Ascend 950PR/Ascend 950DT产品HF32数值精度示意图<a id="zh_cn_topic_mmad_keyfunc_section1_figure2"></a></p><p><img src="'+n+`" alt="Ascend 950PR/Ascend 950DT产品HF32数值精度示意图" title="Ascend 950PR/Ascend 950DT产品HF32数值精度示意图"></p></div><p><strong>使用示例：</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 开启HF32模式</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetHF32Mode</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HF32Mode</span><span class="o">::</span><span class="n">ENABLE</span><span class="p">);</span>
<span class="c1">// 设置舍入模式为向最接近的值舍入，平局时远离零的方式舍入为HF32</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetHF32TransMode</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HF32TransMode</span><span class="o">::</span><span class="n">NEAREST_AWAY</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">MmadParams</span><span class="w"> </span><span class="n">mmadParams</span><span class="p">;</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">m</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">m</span><span class="p">;</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">n</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">n</span><span class="p">;</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">k</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">k</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Mmad</span><span class="p">(</span><span class="n">c1Local</span><span class="p">,</span><span class="w"> </span><span class="n">a2Local</span><span class="p">,</span><span class="w"> </span><span class="n">b2Local</span><span class="p">,</span><span class="w"> </span><span class="n">mmadParams</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetHF32Mode</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HF32Mode</span><span class="o">::</span><span class="n">DISABLE</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetHF32TransMode</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">HF32TransMode</span><span class="o">::</span><span class="n">NEAREST_EVEN</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const u=p(t,[["render",o]]);export{S as __pageData,u as default};
